<?php $analysisKeywords=KeywordAnalysis::keywords($wid);$analysis=KeywordAnalysis::summarize($analysisKeywords);?>
<section class="card stack"><div class="card-header"><div><span class="eyebrow">KEYWORD ANALYSIS</span><h3>Where to focus next</h3><p class="small">Based on saved rankings and the previous observation for each keyword.</p></div><a class="button secondary" href="<?=url('/research?website_id='.$wid)?>">Research new keywords</a></div>
<div class="grid grid-4"><?php foreach(['top10'=>'In the top 10','top20'=>'Positions 11–20','improved'=>'Improved','declined'=>'Declined'] as $key=>$label):?><div class="insight-stat"><strong><?=e($analysis[$key])?></strong><span><?=e($label)?></span></div><?php endforeach;?></div>
<?php $analysisRows=[];foreach($analysisKeywords as $k)$analysisRows[]=['keyword'=>$k['keyword'],'position'=>Ranking::label($k['position']===null?null:(int)$k['position'],$k['ranking_source']),'previous'=>$k['previous_position']===null?'No previous position':'#'.$k['previous_position'],'next'=>KeywordAnalysis::advice($k)];table(['keyword'=>'Keyword','position'=>'Latest position','previous'=>'Previous','next'=>'Suggested next step'],array_slice($analysisRows,0,100));?>
<p class="small"><?=count($analysisRows)>100?'Showing 100 keywords; the performance report includes the full tracked list. ':''?>Search volume is available for <?=$analysis['volume_available']?> of <?=$analysis['total']?> keywords. Suggestions are based on observed rankings, not predicted traffic.</p></section>
